 */
private rankMatchesByScore<C>(
	candidates: C[],
	score: (candidate: C) => ScoredCandidate | null
): Array<{ match: C; confidence: MatchConfidence }> {
	const scored: Array<{ match: C } & ScoredCandidate> = [];

	for (const candidate of candidates) {
		const result = score(candidate);
