const PAGE_WIDTH = 612;
const PAGE_HEIGHT = 792;
const MARGIN = 54; // 0.75 inches
const CONTENT_WIDTH = PAGE_WIDTH - 2 * MARGIN;

// Summary table column positions
const COL_NUM = MARGIN;
const COL_DATE = MARGIN + 30;
const COL_VENDOR = MARGIN + 140;
const COL_AMOUNT = PAGE_WIDTH - MARGIN - 10;

const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/**
 * Current page and vertical write position for the summary tables. Owns page
 * advancement so drawing helpers can only read `page` / move `y` — they never swap
 * the page themselves. `ensureRoom()` is the single place a fresh page starts, which
 * removes the old temporal coupling (every draw site threading `pdfDoc` and manually
 * checking room before writing).
 */
class PageCursor {
	page: PDFPage;
	y: number;

	private constructor(private readonly pdfDoc: PDFDocument) {
		this.page = pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
		this.y = PAGE_HEIGHT - MARGIN;
	}

	/** Begin a fresh page, positioned at its top margin. */
	static start(pdfDoc: PDFDocument): PageCursor {
		return new PageCursor(pdfDoc);
	}

	/** Start a new page if fewer than `minY` points remain on the current one. */
	ensureRoom(minY: number): void {
		if (this.y < minY) {
			this.page = this.pdfDoc.addPage([PAGE_WIDTH, PAGE_HEIGHT]);
			this.y = PAGE_HEIGHT - MARGIN;
		}
	}
}

